// Mock of the bank's statement and debt services (service contract of 1 October 2026), as a Cloudflare Worker.
//
// POST /voice/v1/<service> with {"data": {...}, "call": {...}}. For the bank's test customers it returns the
// answers of the case pack exactly (status code, body, delay); they are in data.js, generated by build_data.py.
// For a customer, card or week that is not in the table it returns the service's 404 of the contract, or a
// 400 INVALID_ARGUMENTS_ERROR where the contract has no 404. Token, headers and "call" are not checked.
import TABLE from "./data.js";

const BASE = "/voice/v1/";
const HEADERS = {
  "content-type": "application/json; charset=utf-8",
  "access-control-allow-origin": "*",
  "access-control-allow-headers": "*",
  "access-control-allow-methods": "GET, POST, OPTIONS",
};
const NOT_FOUND_ORIGIN = "com.freyabank.ivrgateway.ivrchannel.rest.exception.NotFoundException";
const NOT_FOUND = {
  "cards.list": ["FB_IVR_CHANNEL_102", "Müşteriye ait geçerli kart bilgisi bulunamadı."],
  "cards.balance": ["FB_IVR_CHANNEL_120", "Kart bakiye servisi hatası: kart bulunamadı"],
  "statement.week.get": ["FB_IVR_CHANNEL_121", "Kart bulunamadı"],
  "statement.pdf.send": ["FB_IVR_CHANNEL_107", "Pdf dokümanı bulunamadı"],
};

function json(status, body) {
  return new Response(JSON.stringify(body), { status, headers: HEADERS });
}

function guid() {
  return crypto.randomUUID().replace(/-/g, "");
}

function failure(status, code, message, type, rootCause) {
  const id = guid();
  return json(status, {
    result: {
      guid: id, returnCode: code, messageText: message, code, message, type,
      details: { guid: id, rootCause, errorOrigin: "ivr-gateway-test:ivr-channel-v0" },
    },
  });
}

const invalid = (message) => failure(400, "INVALID_ARGUMENTS_ERROR", message, "ERROR", "InvalidArgumentsException");

// no entry: the 404 of the service where the contract has one, else a 400
function missing(service, message) {
  const known = NOT_FOUND[service];
  return known ? failure(404, known[0], known[1], "WARNING", NOT_FOUND_ORIGIN) : invalid(message);
}

function text(value) {
  return value === undefined || value === null ? "" : String(value).trim();
}

// The panel's "Test API Request" can send the text of an unfilled variable; then the first record is used.
const unfilled = (value) => value.includes("{{");
const first = (rows) => Object.keys(rows)[0];

function answerFor(service, data) {
  const rows = TABLE[service];
  if (service === "cards.list" || service === "contact.email.get" || service === "statement.pdf.send") {
    let customer = text(data.customerNo);
    if (!customer) return invalid("customerNo cannot be empty");
    if (unfilled(customer)) customer = first(rows);
    return rows[customer] || missing(service, "customerNo is not valid");
  }
  let card = text(data.cardNumber);
  if (!card) return invalid("card number cannot be empty");
  if (unfilled(card)) card = first(rows);
  if (service === "cards.balance" || service === "statement.week.get") {
    return rows[card] || missing(service, "card number is not valid");
  }
  let week = text(data.newStatementWeek);
  if (!week) return invalid("newStatementWeek cannot be empty");
  const weeks = rows[card];
  if (weeks && unfilled(week)) week = first(weeks);
  return (weeks && weeks[week]) || missing(service, "newStatementWeek is not valid for this card");
}

export default {
  async fetch(request) {
    const path = new URL(request.url).pathname.replace(/\/+$/, "");
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: HEADERS });
    if (request.method === "GET" && (path === "/health" || path === "")) {
      return json(200, { ok: true, services: Object.keys(TABLE).map((name) => "POST " + BASE + name) });
    }
    if (request.method === "POST" && path === "/oauth2/token") {
      return json(200, { access_token: "test-token", token_type: "Bearer", expires_in: 1800 });
    }
    const service = path.startsWith(BASE) ? path.slice(BASE.length) : path.replace(/^\//, "");
    if (request.method !== "POST" || !Object.prototype.hasOwnProperty.call(TABLE, service)) {
      return failure(404, "NOT_FOUND", "no such service: " + request.method + " " + path, "ERROR", "NotFound");
    }
    let body;
    try {
      body = await request.json();
    } catch (error) {
      return invalid("the request body is not JSON");
    }
    const data = body && typeof body === "object" && body.data && typeof body.data === "object" ? body.data : {};
    const answer = answerFor(service, data);
    if (answer instanceof Response) return answer;
    if (answer.delaySeconds) await new Promise((done) => setTimeout(done, answer.delaySeconds * 1000));
    return json(answer.http, answer.response);
  },
};
